// whiteSpaceLookup is white_space::lookup.
func whiteSpaceLookup(c rune) bool {
	switch uint32(c) >> 8 {
	case 0:
		return whiteSpaceMap[uint32(c)&0xff]&1 != 0
	case 22:
		return uint32(c) == 0x1680
	case 32:
		return whiteSpaceMap[uint32(c)&0xff]&2 != 0
	case 48:
		return uint32(c) == 0x3000
	default:
		return false
	}
}
